  wdt:P580 ?start_time. FILTER (?era NOT IN (wd:Q11358452, wd:Q11509224, wd:Q1145058) ) # Exclude ancient times, modern times
#MINUS { ?era wdt:P2348/wdt:P361 wd:Q130436 wd:Q1145058} # exclude sub-eras
