== Early Modern Letters Online ==
=== Years and places of birth and death ===
{{SPARQL2|query=SELECT DISTINCT ?person ?personLabel (URI(CONCAT("http://emlo.bodleian.ox.ac.uk/profile/person/",?emlo)) AS ?emlolink) ?birthyear (IF(isBLANK(?pob),"unknown",?pobLabel) AS ?birthplace) ?deathyear (IF(isBLANK(?pod),"unknown",?podLabel) AS ?deathplace)
WHERE {
   ?person wdt:P1802 ?emlo;
 OPTIONAL { ?person wdt:P569 ?dob }
 OPTIONAL { ?person wdt:P570 ?dod }
 OPTIONAL { ?person wdt:P19 ?pob }
 OPTIONAL { ?person wdt:P20 ?pod }
BIND(YEAR(?dob) as ?birthyear)
BIND(YEAR(?dod) as ?deathyear)
  SERVICE wikibase:label { 
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr,de,nl,es,pl".
  ?pob rdfs:label ?pobLabel.
  ?pod rdfs:label ?podLabel.
  ?person rdfs:label ?personLabel
  }
} ORDER BY DESC(?birthyear)
}}

