  wdt:P1216 ?scheduled.
 ?site2 wdt:P1216 ?scheduled.
 MINUS{?site2 wdt:P4102 []}
# ?site2 wdt:P18 []
 SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en"}
}
