== Overview queries ==
=== Graph visualisation of the entire Khalili data set ===
{{SPARQL|query=SELECT ?item1 ?image ?item1Label ?item2 ?image2 ?item2Label ?edgeLabel
WITH { SELECT ?item1 WHERE {
?item1 wdt:P195?/wdt:P361? wd:Q63160499
} } AS %item1
WITH {SELECT (?item1 AS ?item2) WHERE {INCLUDE %item1} } AS %item2
WHERE {
  INCLUDE %item1.
  INCLUDE %item2.
?item1 ?prop ?item2.
?edge wikibase:directClaim ?prop ; a wikibase:Property
OPTIONAL {?item1 wdt:P18 ?image}
OPTIONAL {?item2 wdt:P18 ?image2}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
}}

=== All items in Khalili Collections, including images, ordered by collection and inventory number ===
{{SPARQL2|query=SELECT ?i ?iLabel ?collLabel ?inv ?image WHERE {
?i wdt:P195 ?coll.
  ?coll wdt:P361? wd:Q63160499.
  OPTIONAL {?i wdt:P217 ?inv}
  OPTIONAL {?i wdt:P18 ?image}
   SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY ?collLabel ?inv
}}

=== 100 most interesting Khalili Collections objects from Hajj and Islamic Art collections ===
{{SPARQL|query=#title:100 most interesting Khalili Collections Islamic objects
SELECT ?item ?itemLabel (SAMPLE(?typeLabel) AS ?what) ?itemDescription ?image ?s WHERE {
  VALUES ?coll {wd:Q66455355 wd:Q66458773} # Islamic Art and Hajj collection
  ?item wdt:P195 ?coll
  FILTER (?item NOT IN (wd:Q3114572, wd:Q109341408, wd:Q2997010, wd:Q108543136, wd:Q107663626) ).# Exclude objects in multiple collections
  ?item wdt:P18 ?image.
  ?item wdt:P31 ?type.
  ?item wikibase:statements ?s
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ar,[AUTO_LANGUAGE],en".
  ?type rdfs:label ?typeLabel. ?item rdfs:label ?itemLabel. ?item schema:description ?itemDescription }
} GROUP BY ?item ?itemLabel ?itemDescription ?image ?s
ORDER BY DESC(?s)
LIMIT 100
}}

=== Enamels of the World collection as a table ===
{{SPARQL|query=#title:Khalili Collection of Enamels of the World
SELECT ?inv ?item ?itemLabel (GROUP_CONCAT(DISTINCT ?locationLabel; separator=', ') AS ?locations) (GROUP_CONCAT(DISTINCT ?creatorLabel; separator=', ') AS ?creators) (GROUP_CONCAT(DISTINCT ?year; separator=', ') AS ?years) WHERE {
  ?item wdt:P195 wd:Q66457023.
  ?item wdt:P217 ?inv.
  OPTIONAL {?item wdt:P1071 ?location}
  OPTIONAL {?item wdt:P571 ?date. BIND(YEAR(?date) AS ?year)}
  OPTIONAL {?item wdt:P170 ?creator FILTER( !CONTAINS(STR(?creator), '/genid/') )}
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en".
                       ?creator rdfs:label ?creatorLabel. ?location rdfs:label ?locationLabel. ?item rdfs:label ?itemLabel}
} GROUP BY ?inv ?item ?itemLabel
ORDER BY ?inv
}}

=== Enamels of the World collection as an image gallery ===
{{SPARQL|query=#title:Khalili Collection of Enamels of the World
#defaultView:ImageGrid{"hide":["?image"]}
SELECT ?inv ?item ?itemLabel ?image (GROUP_CONCAT(DISTINCT ?locationLabel; separator=', ') AS ?locations) (GROUP_CONCAT(DISTINCT ?creatorLabel; separator=', ') AS ?creators) (GROUP_CONCAT(DISTINCT ?year; separator=', ') AS ?years) WHERE {
  ?item wdt:P195 wd:Q66457023.
  ?item wdt:P217 ?inv.
  OPTIONAL {?item wdt:P18 ?img}
  BIND (IF(BOUND(?img), ?img, <http://commons.wikimedia.org/wiki/Special:FilePath/No%20image%20available.svg>) AS ?image)
  OPTIONAL {?item wdt:P1071 ?location}
  OPTIONAL {?item wdt:P571 ?date. BIND(YEAR(?date) AS ?year)}
  OPTIONAL {?item wdt:P170 ?creator FILTER( !CONTAINS(STR(?creator), '/genid/') )}
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en".
                       ?creator rdfs:label ?creatorLabel. ?location rdfs:label ?locationLabel. ?item rdfs:label ?itemLabel}
} GROUP BY ?inv ?item ?itemLabel ?image
ORDER BY ?inv
}}

