== Queries for use building Wikipedia articles ==
=== Overview of the data set, organised into Wikipedia lists ===
{{SPARQL|query=#title:Memory of the World International Register, organised by region
SELECT ?listLabel ?item ?itemLabel (GROUP_CONCAT(?countryname; SEPARATOR=", ") as ?nominators) (YEAR(?date) AS ?year) WHERE {
  ?item p:P1435 ?s. ?s ps:P1435 wd:Q16024238.
  ?s pq:P580 ?date. ?s pq:P361 ?list.
  OPTIONAL{?s pq:P4353 ?country. ?country rdfs:label ?countryname FILTER (lang(?countryname) = 'en')}
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul". }
} GROUP BY ?listLabel ?item ?itemLabel ?date
ORDER BY ?listLabel ?year ?itemLabel
}}

=== All inscriptions, without regions but with English links ===
{{SPARQL|query=#title:Memory of the World International Register with English links
SELECT ?item ?itemLabel (GROUP_CONCAT(?countryname; SEPARATOR=", ") as ?nominators) (YEAR(?date) AS ?year) ?url WHERE {
  ?item p:P1435 ?s. ?s ps:P1435 wd:Q16024238.
  ?s pq:P580 ?date. OPTIONAL{?item p:P973 ?st. ?st ps:P973 ?url FILTER( CONTAINS(STR(?url), "unesco.org/en/") ) }
  OPTIONAL{?s pq:P4353 ?country. ?country rdfs:label ?countryname FILTER (lang(?countryname) = 'en')}
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul". }
} GROUP BY ?item ?itemLabel ?date ?url
ORDER BY ?year ?itemLabel
}}

=== Recreating a specific Wikipedia list ===
{{SPARQL|query=#title:Memory of the World International Register, Latin America and Caribbean
SELECT ?item ?itemLabel (GROUP_CONCAT(DISTINCT ?countryname; SEPARATOR=", ") as ?nominators) (GROUP_CONCAT(DISTINCT ?inst_name; SEPARATOR=", ") as ?locations) (YEAR(?date) AS ?year) WHERE {
  ?item p:P1435 ?s. ?s ps:P1435 wd:Q16024238.
  ?s pq:P580 ?date. ?s pq:P361 wd:Q6815751 .
  OPTIONAL{?s pq:P4353 ?country. ?country rdfs:label ?countryname FILTER (lang(?countryname) = 'en')}
OPTIONAL {?item wdt:P276 ?institution. ?institution rdfs:label ?inst_name FILTER (lang(?inst_name) = 'en') }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul". }
} GROUP BY ?item ?itemLabel ?date
ORDER BY ?year ?itemLabel
}}

