  ?s pq:P4353 ?country . ?country wdt:P31/wdt:P279? wd:Q3624078.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul" }
} GROUP BY ?countryLabel
ORDER BY DESC(?count) ?countryLabel
}}

