=== Heritage added to the register in a given year ===
{{SPARQL|query=#title:Heritage added to the Memory of the World International Register in 2025
SELECT ?item ?itemLabel (GROUP_CONCAT(DISTINCT ?nominatorname; SEPARATOR=", ") AS ?nominators) (GROUP_CONCAT(DISTINCT ?institutionname; SEPARATOR=", ") AS ?institutions) WHERE {
  ?item p:P1435 ?s. ?s ps:P1435 wd:Q16024238. # heritage status
  ?s pq:P580 ?date FILTER(YEAR(?date) = 2025). # added in 2025
  ?s pq:P4353 ?nominator . ?nominator rdfs:label ?nominatorname FILTER (lang(?nominatorname) = 'en')
  OPTIONAL{?item wdt:P276 ?location. ?location rdfs:label ?institutionname FILTER (lang(?institutionname) = 'en')}
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul" }
} GROUP BY ?item ?itemLabel
ORDER BY ?nominators
}}

